function calculateAttendanceLeaveDayCount(startDate, endDate) {
  const start = new Date(startDate);
  const end = new Date(endDate);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end < start) {
    return 0;
  }
  const cursor = new Date(start.getTime());
  let total = 0;
  while (cursor <= end) {
    const weekday = getIsoWeekday(cursor);
    if (weekday >= 1 && weekday <= 5) {
      total += 1;
    }
    cursor.setDate(cursor.getDate() + 1);
  }
  return total;
}

function formatAttendanceBreakWindow(startValue, endValue) {
  const start = String(startValue || "").trim();
  const end = String(endValue || "").trim();
  if (!start || !end) {
    return "";
  }
  return `${start} - ${end}`;
}

function formatAttendanceBreakSummary(group) {
  if (!group) {
    return "-";
  }
  const windows = (Array.isArray(group.break_windows) ? group.break_windows : [])
    .map((item) => {
      const timeWindow = formatAttendanceBreakWindow(item?.start_time, item?.end_time);
      if (!timeWindow) {
        return "";
      }
      const label = String(item?.label || "").trim();
      return label ? `${label}: ${timeWindow}` : timeWindow;
    })
    .filter(Boolean);
  return windows.length > 0 ? windows.join(" | ") : "-";
}

function generateAttendanceTerminalToken() {
  const bytes = new Uint8Array(18);
  window.crypto.getRandomValues(bytes);
  return Array.from(bytes, (value) => value.toString(16).padStart(2, "0")).join("");
}

async function sha256Hex(value) {
  const input = new TextEncoder().encode(String(value || ""));
  const digest = await window.crypto.subtle.digest("SHA-256", input);
  return Array.from(new Uint8Array(digest), (valueByte) => valueByte.toString(16).padStart(2, "0")).join("");
}

function pickValue(row, keys) {
  for (const key of keys) {
    if (row[key] !== undefined && row[key] !== null && row[key] !== "") {
      return row[key];
    }
  }
  return null;
}

function formatDate(value) {
  if (value === null || value === undefined || value === "") {
    return "-";
  }

  const numeric = Number(value);
  const fromMs = Number.isFinite(numeric) ? new Date(numeric) : null;

  if (fromMs && !Number.isNaN(fromMs.getTime())) {
    return fromMs.toLocaleString();
  }

  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return String(value);
  }

  return parsed.toLocaleString();
}

