        setAttendanceGeneratedTerminalToken(`${terminalCode}:${plainToken}`);
        try {
          await navigator.clipboard.writeText(`${terminalCode}:${plainToken}`);
        } catch {
          // Ignore clipboard failures.
        }
        resetAttendanceTerminalForm();
        setAttendanceGeneratedTerminalToken(`${terminalCode}:${plainToken}`);
