    setCompanyProfiles([]);
    setSelectedCompanyId("all");
    setRows([]);
    setError("");
    setLoading(false);
    setCustomers([]);
    setCustomersError("");
    setCustomersLoading(false);
    setCustomerSearchTerm("");
    setEditingCustomerId("");
    setQuotes([]);
    setQuoteItems([]);
    setQuotePriceListRows([]);
    setQuotesError("");
    setQuotesLoading(false);
    setInvoices([]);
    setInvoiceItems([]);
    setInvoicePriceListRows([]);
    setInvoicesError("");
    setInvoicesLoading(false);
    setEditingInvoiceId("");
